{
  "type": "minecraft:item",
  "name": "minecraft:written_book",
  "functions": [
    {
      "function": "minecraft:set_name",
      "name": {
        "text": "Valheim",
        "color": "#58ff4d",
        "bold": true,
        "italic": false
      }
    },
    {
      "function": "minecraft:set_lore",
      "lore": [
        {
          "text": "By Iron Gate AB",
          "color": "#4c9447"
        }
      ],
      "mode": "insert"
    },
    {
      "function": "minecraft:set_written_book_pages",
      "pages": [
        {
          "raw": "ABOUT THIS GAME Valheim is a brutal exploration and survival game for 1-10 players set in a procedurally-generated world inspired by Norse mythology. Craft powerful weapons, construct longhouses, and slay mighty foes to prove yourself to Odin!"
        },
        {
          "raw": "EXPLORE THE TENTH WORLD Explore a world shrouded in mystery. Discover distinct environments with unique enemies to battle, resources to gather and secrets to uncover! Be a viking, sail the open seas in search of lands unknown, and fight bloodthirsty monsters."
        },
        {
          "raw": "BUILD MIGHTY HALLS Raise viking longhouses and build bases that offer reprieve from the dangers ahead. Customise buildings, both inside and out, with a detailed building system. Progress through building tiers to upgrade, expand and defend your base."
        },
        {
          "raw": "GATHER, CRAFT AND SURVIVE Struggle to survive as you gather materials and craft weapons, armor, tools, ships, and defenses. Decorate your hearths and sharpen your blades, grow crops and vegetables, prepare food, brew meads and potions, and progress as you defeat more difficult bosses and discover new recipes and blueprints."
        },
        {
          "raw": "KEY FEATURES: Massive procedurally-generated world where every biome is immersive and distinct, with unique enemies, resources and crafting recipes to discover. Play alone or with up to 10 players on player-hosted dedicated servers and experience unlimited world creation and enemies that scale in difficulty."
        },
        {
          "raw": "Staminabased combat that rewards preparation and skill. Utilize weapon types with unique attacks, different blocking styles, ranged combat, dodges and parries to fight your enemies. Rewarding food system where you cannot starve and are not punished for not eating, instead you gain health, stamina and regeneration buffs depending on what foods you consume."
        },
        {
          "raw": "Intuitive crafting where recipes are discovered as you explore the world, and pick up new resources and ingredients. Flexible building system that takes structural integrity and ventilation into account. Build a small shelter or an entire village, make outposts or claim abandoned buildings as your own. Then customize to your liking."
        },
        {
          "raw": "Sail boats and ships to reach distant lands and explore the sea that offers riches to claim and monsters to fight. Epic boss fights that will test even the best prepared vikings and offer rewards that help you on your journey."
        },
        {
          "raw": "Community-translated languages: In addition to the officially supported languages, Valheim has several community-translated languages. As the name would suggest these are all translated by fans and members of the community, and is an ongoing process. We can't guarantee the quality nor completeness of any specific translation effort."
        },
        {
          "raw": "RECOMMENDED: Requires a 64-bit processor and operating system OS *: Windows 7 or later Processor: i5 3GHz or Ryzen 5 3GHz Memory: 16 GB RAM Graphics: GeForce GTX 1060 or Radeon RX 580 DirectX: Version 11 Network: Broadband Internet connection Storage: 1 GB available space"
        }
      ],
      "mode": "append"
    }
  ]
}

{
  "type": "minecraft:item",
  "name": "minecraft:written_book",
  "functions": [
    {
      "function": "minecraft:set_name",
      "name": {
        "text": "The Hobbit",
        "color": "#54f8c1",
        "bold": true,
        "italic": false
      }
    },
    {
      "function": "minecraft:set_written_book_pages",
      "pages": [
        {
          "raw": "In a hole in the ground there lived a hobbit. Not a nasty, dirty, wet hole, filled with the ends of worms and an oozy smell, nor yet a dry, bare, sandy hole with nothing in it to sit down on or to eat: it was a hobbit-hole, and that means comfort."
        },
        {
          "raw": "It had a perfectly round door like a porthole, painted green, with a shiny yellow brass knob in the exact middle. The door opened on to a tube-shaped hall like a tunnel:"
        },
        {
          "raw": "a very comfortable tunnel without smoke, with panelled walls, and floors tiled and carpeted, provided with polished chairs, and lots and lots of pegs for hats and coats—the hobbit was fond of visitors."
        },
        {
          "raw": "The tunnel wound on and on, going fairly but not quite straight into the side of the hill—The Hill, as all the people for many miles round called it—and many little round doors opened out of it, first on one side and then on another."
        },
        {
          "raw": "No going upstairs for the hobbit: bedrooms, bathrooms, cellars, pantries (lots of these), wardrobes (he had whole rooms devoted to clothes), kitchens, dining-rooms, all were on the same floor, and indeed on the same passage."
        },
        {
          "raw": "The best rooms were all on the left-hand side (going in), for these were the only ones to have windows, deep-set round windows looking over his garden, and meadows beyond, sloping down to the river."
        }
      ],
      "mode": "append"
    },
    {
      "function": "minecraft:set_lore",
      "lore": [
        {
          "text": "By J.R.R. Tolkien",
          "color": "#4baa8a"
        }
      ],
      "mode": "append"
    }
  ]
}

